/**
 * Dominant orientation estimation (0–180°) from image gradients.
 *
 * For 1D barcodes, strong edges are perpendicular to the bar direction;
 * the barcode axis is approximately dominantEdgeAngle + 90°.
 * We return both so the scanner can deskew either way.
 *
 * Not a copy of any commercial SDK — classical computer vision (gradient histogram).
 */

import type { FrameBuffer } from './types';
import { grayscale } from './preprocessors';

export interface OrientationEstimate {
  /** Dominant edge angle in degrees [0, 180) */
  edgeAngleDeg: number;
  /** Suggested barcode-axis angle (edge + 90) mod 180 */
  axisAngleDeg: number;
  /** 0–1 confidence from peak sharpness */
  confidence: number;
}

/**
 * Estimate orientation using a coarse gradient orientation histogram.
 * Operates on a downsampled gray image for speed.
 */
export function estimateOrientation(frame: FrameBuffer): OrientationEstimate {
  const gray = frame.format === 'gray' ? frame : grayscale(frame);
  const w = gray.width;
  const h = gray.height;
  const data = gray.data;

  // Coarse step for speed on mobile
  const step = Math.max(1, Math.floor(Math.min(w, h) / 80));
  const bins = 36; // 5° bins over 180°
  const hist = new Float64Array(bins);

  for (let y = step; y < h - step; y += step) {
    for (let x = step; x < w - step; x += step) {
      const i = y * w + x;
      const gx = data[i + step]! - data[i - step]!;
      const gy = data[i + step * w]! - data[i - step * w]!;
      const mag = Math.abs(gx) + Math.abs(gy);
      if (mag < 30) continue;
      // Angle of gradient normal, fold to [0, 180)
      let ang = (Math.atan2(gy, gx) * 180) / Math.PI;
      if (ang < 0) ang += 180;
      if (ang >= 180) ang -= 180;
      const bin = Math.min(bins - 1, Math.floor((ang / 180) * bins));
      hist[bin]! += mag;
    }
  }

  let peakBin = 0;
  let peakVal = 0;
  let sum = 0;
  for (let b = 0; b < bins; b++) {
    sum += hist[b]!;
    if (hist[b]! > peakVal) {
      peakVal = hist[b]!;
      peakBin = b;
    }
  }

  const edgeAngleDeg = ((peakBin + 0.5) * 180) / bins;
  const axisAngleDeg = (edgeAngleDeg + 90) % 180;
  const confidence = sum > 0 ? Math.min(1, peakVal / (sum / bins + peakVal)) : 0;

  return { edgeAngleDeg, axisAngleDeg, confidence };
}

/**
 * Build a short list of deskew angles to try for near-360° coverage.
 * Uses estimate + offsets; 180° periodicity covers full circle for 1D/2D decoding.
 */
export function buildAngleCandidates(estimate: OrientationEstimate | null): number[] {
  const base: number[] = [0]; // always try upright first (fast path already done externally)

  if (estimate && estimate.confidence > 0.15) {
    const a = estimate.axisAngleDeg;
    const e = estimate.edgeAngleDeg;
    for (const ang of [a, e, a + 90, e + 90]) {
      const n = normalizeAngle(ang);
      if (!base.some((b) => angleDiff(b, n) < 8)) base.push(n);
    }
  }

  // Coverage fillers for arbitrary orientation (kept small for speed)
  for (const ang of [15, 30, 45, 60, 75, 105, 120, 135, 150, 165]) {
    if (!base.some((b) => angleDiff(b, ang) < 10)) base.push(ang);
  }

  return base;
}

function normalizeAngle(deg: number): number {
  let a = deg % 180;
  if (a < 0) a += 180;
  return a;
}

function angleDiff(a: number, b: number): number {
  let d = Math.abs(a - b) % 180;
  if (d > 90) d = 180 - d;
  return d;
}
