/**
 * HybridScanEngine — ML-Kit-inspired pipeline (independent implementation)
 *
 * Architecture mirrors common industrial scanners (not reverse-engineered):
 *   1) Prefer platform BarcodeDetector when available (often ML-backed on Android)
 *   2) Locate / deskew via gradient orientation
 *   3) Multi-angle decode with zxing-wasm as OSS fallback
 *
 * Goal: reliable reads across ~0–360° orientations without commercial SDKs.
 */

import type { BarcodeFormat, BarcodeResult, BoundingBox } from '../types';
import type { FrameBuffer } from '../processing/types';
import { rotateArbitrary } from '../processing/geometry';
import {
  buildAngleCandidates,
  estimateOrientation,
} from '../processing/orientation';
import { BarcodeDecoder } from './BarcodeDecoder';
import { logger } from '../utils/logger';

export interface HybridScanOptions {
  tryFineAngles?: boolean;
  /** Prefer native detector when present */
  preferNative?: boolean;
  maxAngles?: number;
}

export class HybridScanEngine {
  private decoder = new BarcodeDecoder();
  private native: BarcodeDetector | null = null;
  private nativeChecked = false;
  private nativeFormats: string[] = [];

  async init(): Promise<void> {
    await this.decoder.init();
    await this.ensureNative();
  }

  get backendLabel(): string {
    if (this.native) return 'native+zxing';
    return 'zxing';
  }

  get adaptiveMode(): string {
    return this.decoder.adaptiveMode;
  }

  private async ensureNative(): Promise<void> {
    if (this.nativeChecked) return;
    this.nativeChecked = true;

    const BD = (globalThis as unknown as { BarcodeDetector?: typeof BarcodeDetector }).BarcodeDetector;
    if (!BD) {
      logger.info('BarcodeDetector API not available — zxing only');
      return;
    }

    try {
      const formats =
        typeof BD.getSupportedFormats === 'function'
          ? await BD.getSupportedFormats()
          : [
              'qr_code',
              'ean_13',
              'ean_8',
              'code_128',
              'code_39',
              'code_93',
              'codabar',
              'data_matrix',
              'pdf417',
              'aztec',
              'upc_a',
              'upc_e',
              'itf',
            ];
      this.nativeFormats = formats as string[];
      this.native = new BD({ formats: this.nativeFormats });
      logger.info('BarcodeDetector ready', { formats: this.nativeFormats });
    } catch (e) {
      logger.warn('BarcodeDetector init failed', e);
      this.native = null;
    }
  }

  /**
   * Scan one frame. Returns first confident hit.
   */
  async scan(
    frame: FrameBuffer,
    source?: ImageBitmapSource | null,
    options: HybridScanOptions = {}
  ): Promise<BarcodeResult | null> {
    await this.init();
    const preferNative = options.preferNative !== false;
    const t0 = performance.now();

    // ── 1) Platform detector (Chrome/Android often uses Play Services / ML) ──
    if (preferNative && this.native && source) {
      try {
        const hits = await this.native.detect(source);
        if (hits && hits.length > 0) {
          const mapped = mapNative(hits[0]!);
          if (mapped.value) {
            logger.debug('native hit', {
              value: mapped.value,
              ms: (performance.now() - t0).toFixed(1),
            });
            return mapped;
          }
        }
      } catch (e) {
        logger.warn('native detect failed', e);
      }
    }

    // Also try native on ImageData built from frame
    if (preferNative && this.native) {
      try {
        const imageData = frameToImageData(frame);
        const hits = await this.native.detect(imageData);
        if (hits && hits.length > 0) {
          const mapped = mapNative(hits[0]!);
          if (mapped.value) {
            logger.debug('native ImageData hit', {
              value: mapped.value,
              ms: (performance.now() - t0).toFixed(1),
            });
            return mapped;
          }
        }
      } catch {
        /* ignore */
      }
    }

    // ── 2) Orientation estimate + zxing with deskew angles ──
    const orientation = estimateOrientation(frame);
    const angles = buildAngleCandidates(orientation);
    const maxAngles = options.maxAngles ?? (options.tryFineAngles ? 8 : 5);

    // Upright first via adaptive decoder (includes native tryRotate 0/90/180/270)
    let hit = await this.decoder.decode(frame, {
      maxNumberOfSymbols: 1,
      tryFineAngles: false,
      tryRotate: true,
    });
    if (hit) return hit;

    // Deskew by estimated / candidate angles (covers intermediate 0–360 family)
    let tried = 0;
    for (const ang of angles) {
      if (ang === 0) continue;
      if (tried >= maxAngles) break;
      tried++;
      const rotated = rotateArbitrary(frame, ang);
      hit = await this.decoder.decode(rotated, {
        maxNumberOfSymbols: 1,
        tryRotate: true,
        tryFineAngles: false,
        mode: this.decoder.adaptiveMode,
      });
      if (hit) {
        logger.debug('deskew hit', {
          angle: ang,
          value: hit.value,
          ms: (performance.now() - t0).toFixed(1),
        });
        return hit;
      }
    }

    // ── 3) Last resort: fine angles if requested ──
    if (options.tryFineAngles) {
      hit = await this.decoder.decode(frame, {
        maxNumberOfSymbols: 1,
        tryFineAngles: true,
        tryRotate: true,
        mode: 'accurate',
      });
      if (hit) return hit;
    }

    return null;
  }

  resetAdaptive(): void {
    this.decoder.resetAdaptive();
  }
}

function frameToImageData(frame: FrameBuffer): ImageData {
  if (frame.format === 'rgba') {
    return new ImageData(new Uint8ClampedArray(frame.data), frame.width, frame.height);
  }
  const rgba = new Uint8ClampedArray(frame.width * frame.height * 4);
  for (let i = 0, j = 0; i < frame.data.length; i++, j += 4) {
    const v = frame.data[i]!;
    rgba[j] = v;
    rgba[j + 1] = v;
    rgba[j + 2] = v;
    rgba[j + 3] = 255;
  }
  return new ImageData(rgba, frame.width, frame.height);
}

function mapNative(hit: DetectedBarcode): BarcodeResult {
  const box = hit.boundingBox;
  const corners =
    hit.cornerPoints?.map((p) => ({
      x: (p as DOMPointReadOnly).x,
      y: (p as DOMPointReadOnly).y,
    })) ?? undefined;

  const bounds: BoundingBox = {
    x: box?.x ?? 0,
    y: box?.y ?? 0,
    width: box?.width ?? 0,
    height: box?.height ?? 0,
    corners,
  };

  return {
    value: hit.rawValue ?? '',
    format: mapNativeFormat(hit.format),
    bounds,
    timestamp: Date.now(),
  };
}

function mapNativeFormat(format: string): BarcodeFormat {
  const f = format.toLowerCase().replace(/-/g, '_');
  switch (f) {
    case 'qr_code':
      return 'QR_CODE';
    case 'ean_13':
      return 'EAN_13';
    case 'ean_8':
      return 'EAN_8';
    case 'upc_a':
      return 'UPC_A';
    case 'upc_e':
      return 'UPC_E';
    case 'code_128':
      return 'CODE_128';
    case 'code_39':
      return 'CODE_39';
    case 'code_93':
      return 'CODE_93';
    case 'codabar':
      return 'CODABAR';
    case 'itf':
      return 'ITF';
    case 'data_matrix':
      return 'DATA_MATRIX';
    case 'pdf417':
      return 'PDF_417';
    case 'aztec':
      return 'AZTEC';
    default:
      return 'UNKNOWN';
  }
}
