/**
 * Geometry transforms for barcode candidates — Phase 4
 *
 * Fast path: 0 / 90 / 180 / 270° on typed arrays (no canvas).
 * Optional path: arbitrary angle via canvas (slower; use sparingly).
 */

import type { FrameBuffer } from './types';

export type CardinalRotation = 0 | 90 | 180 | 270;

/** Rotate RGBA or gray buffer by a cardinal angle (clockwise). */
export function rotateCardinal(frame: FrameBuffer, degrees: CardinalRotation): FrameBuffer {
  if (degrees === 0) {
    return {
      ...frame,
      data: new Uint8ClampedArray(frame.data),
    };
  }

  if (frame.format === 'gray') {
    return rotateGray(frame, degrees);
  }
  return rotateRgba(frame, degrees);
}

function rotateGray(frame: FrameBuffer, degrees: CardinalRotation): FrameBuffer {
  const w = frame.width;
  const h = frame.height;
  const src = frame.data;

  if (degrees === 180) {
    const out = new Uint8ClampedArray(src.length);
    for (let i = 0, j = src.length - 1; i < src.length; i++, j--) {
      out[i] = src[j]!;
    }
    return { width: w, height: h, format: 'gray', data: out, timestamp: frame.timestamp };
  }

  const outW = h;
  const outH = w;
  const out = new Uint8ClampedArray(outW * outH);

  if (degrees === 90) {
    // (x,y) -> (h-1-y, x)
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        out[x * outW + (h - 1 - y)] = src[y * w + x]!;
      }
    }
  } else {
    // 270: (x,y) -> (y, w-1-x)
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        out[(w - 1 - x) * outW + y] = src[y * w + x]!;
      }
    }
  }

  return {
    width: outW,
    height: outH,
    format: 'gray',
    data: out,
    timestamp: frame.timestamp,
  };
}

function rotateRgba(frame: FrameBuffer, degrees: CardinalRotation): FrameBuffer {
  const w = frame.width;
  const h = frame.height;
  const src = frame.data;

  if (degrees === 180) {
    const out = new Uint8ClampedArray(src.length);
    for (let i = 0, j = src.length - 4; i < src.length; i += 4, j -= 4) {
      out[i] = src[j]!;
      out[i + 1] = src[j + 1]!;
      out[i + 2] = src[j + 2]!;
      out[i + 3] = src[j + 3]!;
    }
    return { width: w, height: h, format: 'rgba', data: out, timestamp: frame.timestamp };
  }

  const outW = h;
  const outH = w;
  const out = new Uint8ClampedArray(outW * outH * 4);

  if (degrees === 90) {
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const si = (y * w + x) * 4;
        const dx = h - 1 - y;
        const dy = x;
        const di = (dy * outW + dx) * 4;
        out[di] = src[si]!;
        out[di + 1] = src[si + 1]!;
        out[di + 2] = src[si + 2]!;
        out[di + 3] = src[si + 3]!;
      }
    }
  } else {
    // 270
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const si = (y * w + x) * 4;
        const dx = y;
        const dy = w - 1 - x;
        const di = (dy * outW + dx) * 4;
        out[di] = src[si]!;
        out[di + 1] = src[si + 1]!;
        out[di + 2] = src[si + 2]!;
        out[di + 3] = src[si + 3]!;
      }
    }
  }

  return {
    width: outW,
    height: outH,
    format: 'rgba',
    data: out,
    timestamp: frame.timestamp,
  };
}

/**
 * Arbitrary rotation (degrees, clockwise) using canvas.
 * Returns RGBA. Slower — use only as fallback for non-cardinal angles.
 */
export function rotateArbitrary(frame: FrameBuffer, degrees: number): FrameBuffer {
  const rad = (degrees * Math.PI) / 180;
  const cos = Math.abs(Math.cos(rad));
  const sin = Math.abs(Math.sin(rad));
  const w = frame.width;
  const h = frame.height;
  const outW = Math.max(1, Math.ceil(w * cos + h * sin));
  const outH = Math.max(1, Math.ceil(w * sin + h * cos));

  const canvas = document.createElement('canvas');
  canvas.width = outW;
  canvas.height = outH;
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  if (!ctx) {
    return rotateCardinal(frame, 0);
  }

  // Source image
  const srcCanvas = document.createElement('canvas');
  srcCanvas.width = w;
  srcCanvas.height = h;
  const sctx = srcCanvas.getContext('2d');
  if (!sctx) return rotateCardinal(frame, 0);

  if (frame.format === 'rgba') {
    sctx.putImageData(new ImageData(new Uint8ClampedArray(frame.data), w, h), 0, 0);
  } else {
    const rgba = new Uint8ClampedArray(w * h * 4);
    for (let i = 0, j = 0; i < frame.data.length; i++, j += 4) {
      const v = frame.data[i]!;
      rgba[j] = v;
      rgba[j + 1] = v;
      rgba[j + 2] = v;
      rgba[j + 3] = 255;
    }
    sctx.putImageData(new ImageData(rgba, w, h), 0, 0);
  }

  ctx.translate(outW / 2, outH / 2);
  ctx.rotate(rad);
  ctx.drawImage(srcCanvas, -w / 2, -h / 2);
  const imageData = ctx.getImageData(0, 0, outW, outH);

  return {
    width: outW,
    height: outH,
    format: 'rgba',
    data: imageData.data,
    timestamp: frame.timestamp,
  };
}

/** Default candidate angles for Phase 4 */
export const CARDINAL_ANGLES: CardinalRotation[] = [0, 90, 180, 270];

/** Extra angles tried only when cardinals fail (costly) */
export const FINE_ANGLES = [-30, -15, 15, 30] as const;
