/**
 * BarcodeDecoder — high-speed path (Phase 4 optimized)
 *
 * Uses zxing-wasm native options:
 *   tryRotate / tryInvert / tryDownscale / tryHarder
 * instead of multiple JS-side rotation + WASM calls (which were much slower).
 *
 * Adaptive strategy:
 *   fast → escalate after consecutive misses → optional fine angles
 */

import type { BarcodeFormat, BarcodeResult, BoundingBox } from '../types';
import type { FrameBuffer } from '../processing/types';
import { FINE_ANGLES, rotateArbitrary } from '../processing/geometry';
import { logger } from '../utils/logger';

type ZXingFormat = string;

interface ZXingReadResult {
  text: string;
  format: ZXingFormat;
  symbology?: string;
  position?: {
    topLeft?: { x: number; y: number };
    topRight?: { x: number; y: number };
    bottomLeft?: { x: number; y: number };
    bottomRight?: { x: number; y: number };
  };
  orientation?: number;
}

type ReadBarcodesFn = (
  input: ImageData | Blob | ArrayBuffer | Uint8Array,
  options?: Record<string, unknown>
) => Promise<ZXingReadResult[]>;

export type ScanMode = 'fast' | 'balanced' | 'accurate';

export interface DecoderOptions {
  maxNumberOfSymbols?: number;
  /** Override adaptive mode */
  mode?: ScanMode;
  /** Restrict formats for speed, e.g. ['QRCode','EAN-13','Code128'] */
  formats?: string[];
  /** After native path fails, try ±15/±30 canvas rotates (slow) */
  tryFineAngles?: boolean;
  /** Override native tryRotate (default follows mode preset) */
  tryRotate?: boolean;
}

/** Presets tuned for live camera scanning */
const MODE_PRESETS: Record<
  ScanMode,
  {
    tryHarder: boolean;
    tryRotate: boolean;
    tryInvert: boolean;
    tryDownscale: boolean;
    tryDenoise: boolean;
    binarizer: string;
    downscaleThreshold: number;
    downscaleFactor: number;
  }
> = {
  fast: {
    tryHarder: false,
    tryRotate: true,
    tryInvert: true,
    tryDownscale: true,
    tryDenoise: false,
    binarizer: 'LocalAverage',
    downscaleThreshold: 400,
    downscaleFactor: 3,
  },
  balanced: {
    tryHarder: true,
    tryRotate: true,
    tryInvert: true,
    tryDownscale: true,
    tryDenoise: false,
    binarizer: 'LocalAverage',
    downscaleThreshold: 500,
    downscaleFactor: 3,
  },
  accurate: {
    tryHarder: true,
    tryRotate: true,
    tryInvert: true,
    tryDownscale: true,
    tryDenoise: false,
    binarizer: 'LocalAverage',
    downscaleThreshold: 600,
    downscaleFactor: 2,
  },
};

export class BarcodeDecoder {
  private readBarcodes: ReadBarcodesFn | null = null;
  private initPromise: Promise<void> | null = null;
  private ready = false;

  /** Consecutive frames without a hit — drives adaptive mode */
  private missStreak = 0;
  private hitStreak = 0;

  get isReady(): boolean {
    return this.ready;
  }

  get adaptiveMode(): ScanMode {
    if (this.missStreak >= 12) return 'accurate';
    if (this.missStreak >= 4) return 'balanced';
    return 'fast';
  }

  async init(): Promise<void> {
    if (this.ready && this.readBarcodes) return;
    if (this.initPromise) return this.initPromise;

    this.initPromise = (async () => {
      try {
        let mod: { readBarcodes?: ReadBarcodesFn };
        try {
          mod = await import('zxing-wasm/reader');
        } catch {
          mod = await import('zxing-wasm');
        }
        if (typeof mod.readBarcodes !== 'function') {
          throw new Error('zxing-wasm did not export readBarcodes');
        }
        this.readBarcodes = mod.readBarcodes;
        this.ready = true;
        logger.info('BarcodeDecoder ready (zxing-wasm, native tryRotate)');
      } catch (e) {
        this.initPromise = null;
        logger.error('BarcodeDecoder init failed', e);
        throw e;
      }
    })();

    return this.initPromise;
  }

  /**
   * Single-barcode decode with adaptive native options.
   * One WASM call covers 0/90/180/270 via tryRotate — do NOT loop JS rotates.
   */
  async decode(
    frame: FrameBuffer,
    options: DecoderOptions = {}
  ): Promise<BarcodeResult | null> {
    await this.init();
    if (!this.readBarcodes) return null;

    const mode = options.mode ?? this.adaptiveMode;
    const preset = MODE_PRESETS[mode];
    const readerOptions: Record<string, unknown> = {
      maxNumberOfSymbols: options.maxNumberOfSymbols ?? 1,
      tryHarder: preset.tryHarder,
      tryRotate: options.tryRotate ?? preset.tryRotate,
      tryInvert: preset.tryInvert,
      tryDownscale: preset.tryDownscale,
      tryDenoise: preset.tryDenoise,
      binarizer: preset.binarizer,
      downscaleThreshold: preset.downscaleThreshold,
      downscaleFactor: preset.downscaleFactor,
    };
    if (options.formats && options.formats.length > 0) {
      readerOptions.formats = options.formats;
    }

    const t0 = performance.now();

    // Primary path: single native call (includes C++ rotations)
    let hit = await this.decodeOnce(frame, readerOptions);
    if (hit) {
      this.onHit();
      logger.debug(`decoded [${mode}]`, {
        value: hit.value,
        ms: (performance.now() - t0).toFixed(1),
      });
      return hit;
    }

    // Optional fine-angle fallback (rare, expensive)
    if (options.tryFineAngles || mode === 'accurate') {
      for (const angle of FINE_ANGLES) {
        const rotated = rotateArbitrary(frame, angle);
        hit = await this.decodeOnce(rotated, {
          ...readerOptions,
          tryRotate: false,
        });
        if (hit) {
          this.onHit();
          logger.debug(`decoded [fine ${angle}°]`, {
            value: hit.value,
            ms: (performance.now() - t0).toFixed(1),
          });
          return hit;
        }
      }
    }

    this.onMiss();
    return null;
  }

  private onHit(): void {
    this.hitStreak++;
    this.missStreak = 0;
  }

  private onMiss(): void {
    this.missStreak++;
    this.hitStreak = 0;
  }

  resetAdaptive(): void {
    this.missStreak = 0;
    this.hitStreak = 0;
  }

  private async decodeOnce(
    frame: FrameBuffer,
    readerOptions: Record<string, unknown>
  ): Promise<BarcodeResult | null> {
    if (!this.readBarcodes) return null;
    const imageData = frameToImageData(frame);
    let results: ZXingReadResult[];
    try {
      results = await this.readBarcodes(imageData, readerOptions);
    } catch (e) {
      logger.warn('decode call failed', e);
      return null;
    }
    if (!results || results.length === 0) return null;
    const first = results[0]!;
    if (!first.text) return null;
    return mapResult(first);
  }
}

function frameToImageData(frame: FrameBuffer): ImageData {
  if (frame.format === 'rgba') {
    const copy = new Uint8ClampedArray(frame.data);
    return new ImageData(copy, frame.width, frame.height);
  }
  const rgba = new Uint8ClampedArray(frame.width * frame.height * 4);
  for (let i = 0, j = 0; i < frame.data.length; i++, j += 4) {
    const v = frame.data[i]!;
    rgba[j] = v;
    rgba[j + 1] = v;
    rgba[j + 2] = v;
    rgba[j + 3] = 255;
  }
  return new ImageData(rgba, frame.width, frame.height);
}

function mapResult(hit: ZXingReadResult): BarcodeResult {
  return {
    value: hit.text ?? '',
    format: mapFormat(hit.format),
    bounds: positionToBounds(hit.position),
    timestamp: Date.now(),
  };
}

function mapFormat(format: ZXingFormat): BarcodeFormat {
  const f = String(format).toLowerCase().replace(/[_-\s]/g, '');
  switch (f) {
    case 'ean8':
      return 'EAN_8';
    case 'ean13':
      return 'EAN_13';
    case 'upca':
      return 'UPC_A';
    case 'upce':
      return 'UPC_E';
    case 'code39':
      return 'CODE_39';
    case 'code93':
      return 'CODE_93';
    case 'code128':
      return 'CODE_128';
    case 'itf':
    case 'interleaved2of5':
      return 'ITF';
    case 'codabar':
      return 'CODABAR';
    case 'databar':
    case 'rss14':
      return 'RSS_14';
    case 'databarexpanded':
    case 'rssexpanded':
      return 'RSS_EXPANDED';
    case 'qrcode':
      return 'QR_CODE';
    case 'microqrcode':
      return 'MICRO_QR';
    case 'datamatrix':
      return 'DATA_MATRIX';
    case 'aztec':
      return 'AZTEC';
    case 'pdf417':
      return 'PDF_417';
    default:
      return 'UNKNOWN';
  }
}

function positionToBounds(
  position?: ZXingReadResult['position']
): BoundingBox {
  if (!position) {
    return { x: 0, y: 0, width: 0, height: 0 };
  }
  const points = [
    position.topLeft,
    position.topRight,
    position.bottomLeft,
    position.bottomRight,
  ].filter(Boolean) as Array<{ x: number; y: number }>;

  if (points.length === 0) {
    return { x: 0, y: 0, width: 0, height: 0 };
  }

  const xs = points.map((p) => p.x);
  const ys = points.map((p) => p.y);
  const minX = Math.min(...xs);
  const maxX = Math.max(...xs);
  const minY = Math.min(...ys);
  const maxY = Math.max(...ys);

  return {
    x: minX,
    y: minY,
    width: maxX - minX,
    height: maxY - minY,
    corners: points,
  };
}
